SELECT interval_code, candle_open_time, signal_mode, COUNT(*) AS n, COUNT(DISTINCT symbol) AS symbols, MIN(generated_at) AS first_gen, MAX(generated_at) AS last_gen, SUM(symbol='XLMUSDT') AS xlm_rows FROM trade_signal WHERE (interval_code = '1h' AND candle_open_time IN ('2026-10-10 16:00:00','2026-10-10 17:00:00','2026-10-10 18:00:00')) OR (interval_code = '5m' AND candle_open_time IN ('2026-10-10 17:50:00','2026-10-10 17:55:00','2026-10-10 18:00:00')) GROUP BY interval_code, candle_open_time, signal_mode ORDER BY interval_code, candle_open_time